import{_ as l,a0 as e,w as p,s as x,I as s,x as i,a1 as a,A as n,ao as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const b=JSON.parse('{"title":"NixOS 系列 #2：如何在虛擬機上安裝 NixOS？ | LCTT x X-CMD","titleTemplate":false,"description":"NixOS 系列 #2：如何在虛擬機上安裝 NixOS？ | LCTT (202303) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"NixOS 系列 #2：如何在虛擬機上安裝 NixOS？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"NixOS 系列 #2：如何在虛擬機上安裝 NixOS？ | LCTT (202303) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202303/20230227.0 ⭐️⭐️ NixOS Series 2 How to Install NixOS on a Virtual Machine","title":"NixOS 系列 #2：如何在虛擬機上安裝 NixOS？","tag":"202303","desc":""},"relativePath":"202303/20230227.0 ⭐️⭐️ NixOS Series 2 How to Install NixOS on a Virtual Machine.md","filePath":"[post].md"}'),u={name:"202303/20230227.0 ⭐️⭐️ NixOS Series 2 How to Install NixOS on a Virtual Machine.md"};function m(g,t,d,S,h,O){const r=e("Link");return p(),x("div",null,[t[28]||(t[28]=s("h1",{id:"nixos-系列-2-如何在虛擬機上安裝-nixos",tabindex:"-1"},[i("NixOS 系列 #2：如何在虛擬機上安裝 NixOS？ "),s("a",{class:"header-anchor",href:"#nixos-系列-2-如何在虛擬機上安裝-nixos","aria-label":"Permalink to “NixOS 系列 #2：如何在虛擬機上安裝 NixOS？”"},"​")],-1)),t[29]||(t[29]=s("p",null,"如果你可以在任何 Linux 發行版上使用 Nix 包管理器，為什麼還要安裝 NixOS？",-1)),t[30]||(t[30]=s("p",null,"在使用 NixOS 幾天之前，我經常想知道同樣的事情。",-1)),s("p",null,[t[1]||(t[1]=i("當我意識到這些好處後，我就寫了這篇文章來幫助你瞭解 ",-1)),a(r,{href:"https://linux.cn/article-15606-1.html"},{default:n(()=>[...t[0]||(t[0]=[i("為什麼你要考慮使用 NixOS",-1)])]),_:1}),t[2]||(t[2]=i("。如果你已經閲讀了本系列的第一篇文章，那麼你已經知道自己想要什麼了。",-1))]),t[31]||(t[31]=s("p",null,"那麼，如何開始呢？考慮到它對許多人來説可能是一種新體驗，你應該用它替換日常使用的系統還是將其安裝為虛擬機？",-1)),s("p",null,[t[4]||(t[4]=i("我建議在你想要將其替換為你的主要操作系統之前在虛擬機上使用 NixOS。這適用於你想嘗試的任何新事物，特別是 ",-1)),a(r,{href:"https://itsfoss.com/advanced-linux-distros/"},{default:n(()=>[...t[3]||(t[3]=[i("先進的 Linux 發行版",-1)])]),_:1}),t[5]||(t[5]=i("，例如 NixOS。",-1))]),t[32]||(t[32]=o('<h3 id="使用-virtualbox-在-vm-中安裝-nixos" tabindex="-1">使用 VirtualBox 在 VM 中安裝 NixOS <a class="header-anchor" href="#使用-virtualbox-在-vm-中安裝-nixos" aria-label="Permalink to “使用 VirtualBox 在 VM 中安裝 NixOS”">​</a></h3><p>在本教程中，我將使用 VirtualBox。</p><p>如果你使用的是 Ubuntu 並且不關心是否擁有最新版本，那麼可以使用一個命令安裝 VirtualBox：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>sudo apt install virtualbox</span></span></code></pre></div><p>想要安裝最新版本？你可以參考下面的指南：</p>',5)),s("blockquote",null,[s("p",null,[s("strong",null,[a(r,{href:"https://itsfoss.com/install-virtualbox-ubuntu/"},{default:n(()=>[...t[6]||(t[6]=[i("如何在 Ubuntu 上安裝 VirtualBox（初學者教程）",-1)])]),_:1})])])]),s("p",null,[t[8]||(t[8]=i("如果你使用 Ubuntu 以外的任何發行版，你可以 ",-1)),a(r,{href:"https://www.virtualbox.org/wiki/Linux_Downloads"},{default:n(()=>[...t[7]||(t[7]=[i("按照其官方下載頁面的下載説明進行操作",-1)])]),_:1}),t[9]||(t[9]=i("。",-1))]),t[33]||(t[33]=s("p",null,"成功安裝 VirtualBox 後，讓我們從第一步開始。",-1)),t[34]||(t[34]=s("h4",{id:"步驟-1-獲-取nixos-的-iso-鏡像",tabindex:"-1"},[i("步驟 1：獲 取NixOS 的 ISO 鏡像 "),s("a",{class:"header-anchor",href:"#步驟-1-獲-取nixos-的-iso-鏡像","aria-label":"Permalink to “步驟 1：獲 取NixOS 的 ISO 鏡像”"},"​")],-1)),s("p",null,[t[11]||(t[11]=i("你需要前往 NixOS ",-1)),a(r,{href:"https://nixos.org/download.html"},{default:n(()=>[...t[10]||(t[10]=[i("官方下載頁面",-1)])]),_:1}),t[12]||(t[12]=i("。",-1))]),t[35]||(t[35]=o('<p>在 “NixOS: the Linux distribution” 部分，你會找到帶有 GNOME 和 KDE 桌面的 ISO。</p><p>當然，也有最小化 ISO，但我建議使用兩者之一（GNOME 和 KDE）：</p><p><img src="https://itsfoss.com/content/images/2023/02/Download-NixOS-ISO-file.png" alt="下載 NixOS ISO 文件"></p><p>對於本教程，我將使用 GNOME。</p><p>請記住，你可以選擇 GNOME 和 KDE 兩種<ruby>立付桌面環境<rt>Live Desktop</rt></ruby>。</p><p>而在安裝過程中，你可以選擇自己喜歡的桌面環境，包括 <strong>Xfce、Pantheon、Cinnamon、MATE</strong> 等等！</p><h4 id="步驟-2-在-virtualbox-中創建虛擬機" tabindex="-1">步驟 2：在 VirtualBox 中創建虛擬機 <a class="header-anchor" href="#步驟-2-在-virtualbox-中創建虛擬機" aria-label="Permalink to “步驟 2：在 VirtualBox 中創建虛擬機”">​</a></h4><p>打開 VirtualBox 並單擊 “<ruby>新建<rt>New</rt></ruby>” 按鈕添加新的虛擬機：</p><p><img src="https://itsfoss.com/content/images/2023/02/click-on-new-to-add-new-virtual-machine.png" alt="截圖顯示瞭如何點擊新建按鈕來添加新的虛擬機"></p><p>它將打開一個提示，要求你添加有關要添加的虛擬機的信息。</p><p>你可以先命名虛擬機：</p><ul><li>為你的虛擬機命名，以便你可以識別它是 NixOS 系統。所以我將其命名為 “NixOS”。</li><li>選擇你剛剛下載的 ISO 鏡像。</li><li>選擇 “Linux” ISO 類型。</li><li>並在版本選擇 “<ruby>其它 Linux（64 位）<rt>Other Linux (64-bit)</rt></ruby>”。</li></ul><p><img src="https://itsfoss.com/content/images/2023/02/Add-NixOS-ISO-to-VirtualBox.png" alt=""></p><p>選擇所有內容後，單擊 “<ruby>下一步<rt>Next</rt></ruby>” 按鈕。</p><p>接下來，系統會要求你選擇基本內存（RAM）、要分配給此虛擬機的處理器以及存儲空間。</p><p>雖然 NixOS 沒有提到官方要求，但我建議你為此安裝至少擁有 <strong>4GB RAM</strong>、<strong>2-4 個處理器內核</strong>和 <strong>30GB 空間</strong>：</p><p><img src="https://itsfoss.com/content/images/2023/02/select-hardware-for-NixOS-VM-1.png" alt="選擇 NixOS 虛擬機的硬件"></p><p>最後，它會顯示你為此虛擬機所做選擇的摘要：</p><p><img src="https://itsfoss.com/content/images/2023/02/summery-of-NixOS-VM-install.png" alt="NixOS 虛擬機 安裝摘要"></p><p>如果一切正常，請單擊 “<ruby>完成<rt>Finish</rt></ruby>” 按鈕，它將為你創建一個 NixOS 虛擬機。</p><h4 id="步驟-3-安裝-nixos" tabindex="-1">步驟 3：安裝 NixOS <a class="header-anchor" href="#步驟-3-安裝-nixos" aria-label="Permalink to “步驟 3：安裝 NixOS”">​</a></h4><p>創建完虛擬機後，你為 NixOS 虛擬機指定的名稱應該顯示在 VirtualBox 的虛擬機列表中。</p><p>選擇 “NixOS” 虛擬機並單擊“開始”按鈕：</p><p><img src="https://itsfoss.com/content/images/2023/02/start-the-NixOS-VM.png" alt="開始 NixOS 虛擬機"></p><p>它將啓動 NixOS <ruby>立付桌面環境<rt>Live Desktop</rt></ruby>，以便你可以試用 Linux 發行版。</p><h5 id="選擇安裝語言" tabindex="-1">選擇安裝語言 <a class="header-anchor" href="#選擇安裝語言" aria-label="Permalink to “選擇安裝語言”">​</a></h5><p>啓動進入 NixOS 後，安裝程序將啓動並要求你設置安裝程序的首選語言：</p><p><img src="https://itsfoss.com/content/images/2023/02/1.-choose-the-language-of-NixOS-installer.png" alt="選擇安裝時的首選語言"></p><h5 id="選擇地區和時區" tabindex="-1">選擇地區和時區 <a class="header-anchor" href="#選擇地區和時區" aria-label="Permalink to “選擇地區和時區”">​</a></h5><p>接下來，選擇你所在的地區和區域。如果你不知道這一點，你可以從地圖上選擇你的國家，它會為你設置。</p><p>選擇區域和區域後，它還會選擇系統的首選語言、數字和日期區域設置。</p><p>當然，你可以根據需要進行更改，但對於大多數用户而言，選定的選項就可以正常工作：</p><p><img src="https://itsfoss.com/content/images/2023/02/2.-choose-the-region-and-zone-for-NixOS.png" alt="選擇地區和時區"></p><h5 id="選擇鍵盤佈局" tabindex="-1">選擇鍵盤佈局 <a class="header-anchor" href="#選擇鍵盤佈局" aria-label="Permalink to “選擇鍵盤佈局”">​</a></h5><p>接下來，你將必須設置鍵盤佈局。對於大多數用户來説，默認設置的 “English (US)” 應該可以正常工作。</p><p>如果你要進行其他操作，則可以在繼續之前測試你的鍵盤配置。</p><p><img src="https://itsfoss.com/content/images/2023/02/3.-select-Keyboard-layout-for-NixOS.png" alt="選擇鍵盤格式"></p><p>之後，系統會要求你創建一個用户併為該用户設置密碼。</p><p>你可以選擇為虛擬機保留一個強密碼或任何隨機密碼。</p><p><img src="https://itsfoss.com/content/images/2023/02/4.-create-user-and-set-password-for-NixOS.png" alt="創建用户"></p><h5 id="選擇你喜歡的桌面環境" tabindex="-1">選擇你喜歡的桌面環境 <a class="header-anchor" href="#選擇你喜歡的桌面環境" aria-label="Permalink to “選擇你喜歡的桌面環境”">​</a></h5><p>使用 NixOS，你可以選擇以下桌面環境：</p><ul><li>GNOME</li><li>KDE（定製的最佳選擇）</li><li>Xfce</li><li>Pantheon（ElementaryOS 附帶的桌面環境）</li><li>Cinnamon</li><li>Enlightenment</li><li>LXQt</li></ul><p><img src="https://itsfoss.com/content/images/2023/02/5.-choose-desktop-environment-for-NixOS.png" alt="選擇桌面環境"></p><h5 id="在-nixos-上使用非自由軟件" tabindex="-1">在 NixOS 上使用非自由軟件 <a class="header-anchor" href="#在-nixos-上使用非自由軟件" aria-label="Permalink to “在 NixOS 上使用非自由軟件”">​</a></h5><p>NixOS 遵循與 Fedora 類似的方法，你必須選擇是否需要非自由軟件。</p><p>我建議你啓用非自由包：</p><p><img src="https://itsfoss.com/content/images/2023/02/6.-Allow-unfree-software.png" alt="啓用非自由軟件包"></p><h5 id="分區部分" tabindex="-1">分區部分 <a class="header-anchor" href="#分區部分" aria-label="Permalink to “分區部分”">​</a></h5><p>由於這是一個虛擬機指南，我建議你使用自動對磁盤進行分區的 “<ruby>擦除磁盤<rt>Erase disk</rt></ruby>” 選項！</p><p><img src="https://itsfoss.com/content/images/2023/02/7.-select-erase-disk-option-while-installing-NixOS.png" alt="自動分區"></p><p>完成後，它將為你提供你所做選擇的摘要：</p><p><img src="https://itsfoss.com/content/images/2023/02/8.-summery-of-NixOS-installation-options-in-VM.png" alt="安裝選擇摘要"></p><p>如果一切正常，請單擊 “<ruby>安裝<rt>Install</rt></ruby>” 按鈕，它將開始安裝。</p><h5 id="不要重啓而是關閉虛擬機" tabindex="-1">不要重啓而是關閉虛擬機 <a class="header-anchor" href="#不要重啓而是關閉虛擬機" aria-label="Permalink to “不要重啓而是關閉虛擬機”">​</a></h5><p>安裝完成後，你可以選擇重新啓動虛擬機。</p><p>如果你這樣做，<strong>它將再次加載安裝程序</strong>！</p><p>要解決此問題，你必須更改引導順序。</p><p>為此，請在安裝完成後關閉虛擬機。</p><p>要關閉虛擬機，請從“<ruby>文件<rt>File</rt></ruby>”菜單中選擇 “<ruby>關閉<rt>Close</rt></ruby>” 選項，然後選擇 “<ruby>關閉虛擬機電源<rt>Power off the machine</rt></ruby>” 選項：</p><p><img src="https://itsfoss.com/content/images/2023/02/poweroff-VM.png" alt=""></p><h5 id="更改-virtualbox-中的啓動順序" tabindex="-1">更改 VirtualBox 中的啓動順序 <a class="header-anchor" href="#更改-virtualbox-中的啓動順序" aria-label="Permalink to “更改 VirtualBox 中的啓動順序”">​</a></h5><p>要更改 NixOS 虛擬機 中的啓動順序，請打開該虛擬機的設置：</p><p><img src="https://itsfoss.com/content/images/2023/02/open-settings-for-VM-in-VirtualBox.png" alt=""></p><p>在設置中，選擇 “<ruby>系統<rt>System</rt></ruby>”，你將找到啓動順序。</p><p>在這裏，選擇 “<ruby>硬盤<rt>Hard Disk</rt></ruby>” 並使用選項旁邊的<strong>向上箭頭</strong>圖標並將其設為啓動的第一個選項：</p><p><img src="https://itsfoss.com/content/images/2023/02/how-to-change-the-boot-order-in-VirtualBox.gif" alt="改變啓動順序"></p><p>按下 “<ruby>確定<rt>OK</rt></ruby>”，它將保存你所做的更改。</p><p><strong>或者</strong>，你可以移除我們添加的用於啓動安裝的光盤（ISO 鏡像）。</p><h4 id="步驟-4-從-nixos-安裝啓動" tabindex="-1">步驟 4：從 NixOS 安裝啓動 <a class="header-anchor" href="#步驟-4-從-nixos-安裝啓動" aria-label="Permalink to “步驟 4：從 NixOS 安裝啓動”">​</a></h4><p>現在，啓動你的 NixOS 虛擬機，你將看到一個 GRUB 屏幕：</p><p><img src="https://itsfoss.com/content/images/2023/02/NixOS-grub-screen.png" alt="NixOS grub"></p><p>選擇默認選項，它將帶你進入帶有 GNOME 桌面的全新 NixOS 安裝。</p><p><img src="https://itsfoss.com/content/images/2023/02/running-NixOS-in-VM.png" alt="運行 NixOS"></p><p>就是這些了！<strong>請繼續探索 NixOS！</strong></p><h3 id="總結" tabindex="-1">總結 <a class="header-anchor" href="#總結" aria-label="Permalink to “總結”">​</a></h3><p>這是關於如何在 VirtualBox 上安裝 NixOS 的快速指南。</p><p>對於 NixOS 教程系列的下一部分，我將分享有關<strong>安裝和刪除包</strong>的建議。</p><p>💬 <em>敬請期待本系列的下一部分。在那之前，請隨時分享你對 NixOS 的看法或在遵循指南時遇到任何問題！</em></p><hr>',80)),s("p",null,[t[14]||(t[14]=i("via: ",-1)),a(r,{href:"https://itsfoss.com/install-nixos-vm/"},{default:n(()=>[...t[13]||(t[13]=[i("https://itsfoss.com/install-nixos-vm/",-1)])]),_:1})]),s("p",null,[t[19]||(t[19]=i("作者：",-1)),a(r,{href:"https://itsfoss.com/author/sagar/"},{default:n(()=>[...t[15]||(t[15]=[i("Sagar Sharma",-1)])]),_:1}),t[20]||(t[20]=i(" 選題：",-1)),a(r,{href:"https://github.com/lkxed/"},{default:n(()=>[...t[16]||(t[16]=[i("lkxed",-1)])]),_:1}),t[21]||(t[21]=i(" 譯者：",-1)),a(r,{href:"https://github.com/geekpi"},{default:n(()=>[...t[17]||(t[17]=[i("geekpi",-1)])]),_:1}),t[22]||(t[22]=i(" 校對：",-1)),a(r,{href:"https://github.com/wxy"},{default:n(()=>[...t[18]||(t[18]=[i("wxy",-1)])]),_:1})]),s("p",null,[t[25]||(t[25]=i("本文由 ",-1)),a(r,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[23]||(t[23]=[i("LCTT",-1)])]),_:1}),t[26]||(t[26]=i(" 原創編譯，",-1)),a(r,{href:"https://linux.cn/"},{default:n(()=>[...t[24]||(t[24]=[i("Linux中國",-1)])]),_:1}),t[27]||(t[27]=i(" 榮譽推出",-1))])])}const k=l(u,[["render",m]]);export{b as __pageData,k as default};
